-- Тема 03: варианты ответов выровнены по длине и форме (56 исправлений в 17 вопросах), ключи не меняются.
-- Источник: scripts/questions/085_option_length_topic03.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Какой файл параметров сервера считывается последним?', 'postgresql.conf', 'Файл postgresql.conf', 'Считывается раньше, его значения может переопределить postgresql.auto.conf.', NULL),
        ('option', 'Какой файл параметров сервера считывается последним?', 'pg_hba.conf', 'Файл pg_hba.conf', 'Это файл аутентификации, он считывается отдельно и параметры сервера не задаёт.', NULL),
        ('option', 'Какой файл параметров сервера считывается последним?', 'postgresql.auto.conf', 'Файл postgresql.auto.conf', 'Среди файлов параметров сервера считывается последним, после postgresql.conf.', NULL),
        ('option', 'Какой файл параметров сервера считывается последним?', 'pg_ident.conf', 'Файл pg_ident.conf', 'Это отображение внешних имён пользователей (ОС, сертификатов) на роли.', NULL),
        ('option', 'Что означает context = postmaster в pg_settings?', 'Изменить может только суперпользователь в своём сеансе', 'Менять в сеансе может суперпользователь', 'Это контекст superuser: менять в сеансе может суперпользователь или роль с привилегией SET на параметр.', NULL),
        ('option', 'Что означает context = postmaster в pg_settings?', 'Параметр нельзя изменить', 'Параметр изменить нельзя, он задан сервером', 'Это контекст internal.', NULL),
        ('option', 'В транзакции выполнили SET work_mem = ''64MB'', затем ROLLBACK. Какое будет значение?', '64MB', 'Значение 64MB, заданное в транзакции', 'Изменение отменилось вместе с транзакцией.', NULL),
        ('option', 'В транзакции выполнили SET work_mem = ''64MB'', затем ROLLBACK. Какое будет значение?', 'То, что действовало до начала транзакции', 'Значение, действовавшее до транзакции', 'Команда SET транзакционна, откат возвращает прежнее значение.', NULL),
        ('option', 'Чем имя пользовательского параметра должно отличаться от стандартного?', 'Содержать точку, например myapp.currency_code', 'Содержать точку, как в myapp.currency_code', 'Имя вида префикс.параметр отличает его от параметров сервера.', NULL),
        ('option', 'Чем имя пользовательского параметра должно отличаться от стандартного?', 'Начинаться с подчёркивания', 'Начинаться с символа подчёркивания в имени', 'Подчёркивание не делает параметр пользовательским.', NULL),
        ('option', 'Чем имя пользовательского параметра должно отличаться от стандартного?', 'Быть в верхнем регистре', 'Быть записанным в верхнем регистре', 'Регистр имени параметра значения не имеет.', NULL),
        ('option', 'Чем имя пользовательского параметра должно отличаться от стандартного?', 'Начинаться с префикса custom_', 'Начинаться с префикса custom_ или app_', 'Такого требования нет.', NULL),
        ('option', 'Почему ALTER SYSTEM SET work_mem TO ''16mb'' завершается ошибкой?', 'Единицы измерения чувствительны к регистру, нужно ''16MB''', 'Единица MB пишется с учётом регистра: ''16MB''', 'Допустимы B, kB, MB, GB и TB с учётом регистра.', NULL),
        ('option', 'Почему ALTER SYSTEM SET work_mem TO ''16mb'' завершается ошибкой?', 'Значение превышает максимум', 'Значение превышает допустимый максимум', '16 МБ в допустимых пределах.', NULL),
        ('option', 'Как задать work_mem = 32MB для сеанса прямо при запуске psql?', 'psql --work-mem=32MB', 'Ключ psql --work-mem=32MB при запуске', 'Такого ключа у psql нет.', NULL),
        ('option', 'Как задать work_mem = 32MB для сеанса прямо при запуске psql?', '\set work_mem 32MB в .psqlrc', '\set work_mem 32MB в файле .psqlrc', 'Команда \set задаёт переменную psql, а не параметр сервера.', NULL),
        ('option', 'Как задать work_mem = 32MB для сеанса прямо при запуске psql?', 'Переменная PGWORKMEM=32MB', 'Переменная окружения PGWORKMEM=32MB', 'Такой переменной нет.', NULL),
        ('option', 'Как задать work_mem = 32MB для сеанса прямо при запуске psql?', 'Переменная окружения PGOPTIONS=''-c work_mem=32MB''', 'Переменная PGOPTIONS=''-c work_mem=32MB''', 'PGOPTIONS передаёт серверу параметры при подключении.', NULL),
        ('option', 'Чем директива include_if_exists отличается от include?', 'Отсутствие файла не считается ошибкой', 'Отсутствие файла не считается ошибкой при запуске', 'Файл подключается, только если существует.', NULL),
        ('option', 'Чем директива include_if_exists отличается от include?', 'Читается только при запуске сервера', 'Читается при запуске сервера, но не при reload', 'Все директивы обрабатываются и при перечитывании конфигурации.', NULL),
        ('option', 'Чем директива include_if_exists отличается от include?', 'Подключает файлы из каталога', 'Подключает все файлы из каталога', 'Это делает include_dir (только файлы с окончанием .conf).', NULL),
        ('option', 'Чем директива include_if_exists отличается от include?', 'Значения из такого файла имеют наивысший приоритет', 'Его значения имеют наивысший приоритет', 'Приоритет определяется порядком чтения: побеждает последняя строка.', NULL),
        ('option', 'Что означает значение pending_restart = true в pg_settings?', 'В строке файла конфигурации ошибка', 'В строке файла конфигурации обнаружена ошибка', 'Ошибки видны в столбце error представления pg_file_settings.', NULL),
        ('option', 'Что означает значение pending_restart = true в pg_settings?', 'Значение изменено в файле, но вступит в силу только после перезапуска сервера', 'Значение изменено в файле, действует после перезапуска', 'Такие параметры имеют context = postmaster.', 'Значение изменено в файле, но вступит в силу только после перезапуска сервера; такие параметры имеют context = postmaster.'),
        ('option', 'Что означает значение pending_restart = true в pg_settings?', 'Сервер перезапустится автоматически', 'Сервер перезапустится сам при следующем reload', 'Перезапуск выполняет администратор.', NULL),
        ('option', 'Как в пакете Ubuntu сервер находит postgresql.conf, если файл лежит вне каталога данных?', 'Через символическую ссылку в PGDATA', 'Через символическую ссылку в каталоге PGDATA', 'Ссылки нет: путь передаётся при запуске.', NULL),
        ('option', 'Как в пакете Ubuntu сервер находит postgresql.conf, если файл лежит вне каталога данных?', 'Через переменную окружения PGCONF', 'Через переменную окружения PGCONF сервера', 'Такой переменной сервер не использует.', NULL),
        ('option', 'Как в пакете Ubuntu сервер находит postgresql.conf, если файл лежит вне каталога данных?', 'Путь передаётся в параметре config_file в командной строке запуска', 'Путь передаётся параметром config_file при запуске', 'Его видно в выводе ps для основного процесса postgres.', 'Путь передаётся в параметре config_file в командной строке запуска: его видно в выводе ps для основного процесса postgres.'),
        ('option', 'Что делает команда RESET work_mem в сеансе?', 'Отменяет действие SET в сеансе: возвращает значение, которое было бы без него', 'Отменяет действие SET, возвращая значение без него', 'Это значение показывает столбец reset_val; обычно оно совпадает с действовавшим в начале сеанса.', 'Возвращает значение, которое было бы без SET: его показывает столбец reset_val; обычно оно совпадает с действовавшим в начале сеанса.'),
        ('option', 'Что делает команда RESET work_mem в сеансе?', 'Возвращает встроенное значение по умолчанию', 'Возвращает встроенное значение boot_val по умолчанию', 'Значение по умолчанию (boot_val) может отличаться от заданного в файлах.', NULL),
        ('option', 'Что делает команда RESET work_mem в сеансе?', 'Удаляет параметр из postgresql.auto.conf', 'Удаляет параметр из файла postgresql.auto.conf', 'Это делает ALTER SYSTEM RESET.', NULL),
        ('option', 'Что делает команда RESET work_mem в сеансе?', 'Перечитывает файлы конфигурации', 'Перечитывает файлы конфигурации сервера', 'Это делает pg_reload_conf().', NULL),
        ('option', 'Что верно для пользовательских параметров вида myapp.currency_code?', 'Перед использованием их нужно объявить командой ALTER SYSTEM', 'Перед использованием их нужно объявить ALTER SYSTEM', 'Нет. Для создания такого параметра в сеансе достаточно SET. В PostgreSQL 16 записать его через ALTER SYSTEM можно, если имя уже известно текущему сеансу, например после SET, и у роли есть необходимые права.', NULL),
        ('option', 'Что верно для пользовательских параметров вида myapp.currency_code?', 'Их можно создать прямо в сеансе командой SET или функцией set_config', 'Их можно создать в сеансе командой SET', 'После этого значение читается через current_setting.', 'Их можно создать прямо в сеансе командой SET или функцией set_config; после этого значение читается через current_setting.'),
        ('option', 'Что верно для пользовательских параметров вида myapp.currency_code?', 'Их имя не должно содержать точку', 'Их имя не должно содержать точку и префикс', 'Наоборот, точка обязательна: она отличает их от стандартных параметров.', NULL),
        ('option', 'Что верно для пользовательских параметров вида myapp.currency_code?', 'Их можно задать в файле конфигурации, и они будут инициализироваться во всех сеансах', 'Их можно задать в файле конфигурации для всех сеансов', 'Так их используют как глобальные настройки приложения.', 'Их можно задать в файле конфигурации, и они будут инициализироваться во всех сеансах: так их используют как глобальные настройки приложения.'),
        ('option', 'Что означает context = sighup в pg_settings?', 'Изменить в своём сеансе может только привилегированная роль', 'Изменить в сеансе может привилегированная роль', 'Это context = superuser: суперпользователь или роль, которой выдано право SET на этот параметр.', NULL),
        ('option', 'Что означает context = sighup в pg_settings?', 'Для применения достаточно перечитать файлы конфигурации', 'Достаточно перечитать файлы конфигурации', 'Например, pg_reload_conf() или pg_ctl reload.', NULL),
        ('option', 'На сервере работают несколько независимых кластеров PostgreSQL. В текущем сеансе SHOW data_directory возвращает /var/lib/postgresql/16/main. Для какого кластера вызов SELECT pg_reload_conf(); из этого сеанса инициирует перечитывание конфигурации?', 'Только для текущей базы данных внутри кластера', 'Для текущей базы данных внутри кластера', 'Перечитывание конфигурации относится к экземпляру сервера, а не к одной базе данных.', NULL),
        ('option', 'На сервере работают несколько независимых кластеров PostgreSQL. В текущем сеансе SHOW data_directory возвращает /var/lib/postgresql/16/main. Для какого кластера вызов SELECT pg_reload_conf(); из этого сеанса инициирует перечитывание конфигурации?', 'Только для кластера с каталогом данных /var/lib/postgresql/16/main', 'Для кластера с каталогом /var/lib/postgresql/16/main', 'Сигнал получает основной процесс того сервера, к которому подключён сеанс; он передаёт сигнал своим дочерним процессам.', NULL),
        ('option', 'Запрос SELECT setting, unit FROM pg_settings WHERE name = ''work_mem''; вернул 4096 и kB. Чему равен work_mem?', '4096 МБ', '4096 МБ: число из setting без пересчёта', 'unit = kB означает килобайты; 4096 МБ — это 4 ГБ.', NULL),
        ('option', 'Запрос SELECT setting, unit FROM pg_settings WHERE name = ''work_mem''; вернул 4096 и kB. Чему равен work_mem?', '4 МБ: значение указано в единицах из столбца unit, то есть 4096 КБ', '4 МБ: единица берётся из столбца unit', 'В столбце setting число, а единицу измерения задаёт столбец unit.', 'Значение указано в единицах из столбца unit: 4096 КБ, то есть 4 МБ. В столбце setting число, а единицу измерения задаёт столбец unit.'),
        ('option', 'Запрос SELECT setting, unit FROM pg_settings WHERE name = ''work_mem''; вернул 4096 и kB. Чему равен work_mem?', '4096 байт', '4096 байт: стандартная единица ОС', 'Единица указана в столбце unit — это килобайты, а не байты.', NULL),
        ('option', 'Запрос SELECT setting, unit FROM pg_settings WHERE name = ''work_mem''; вернул 4096 и kB. Чему равен work_mem?', '4096 страниц по 8 КБ', '4096 страниц по 8 КБ, как у shared_buffers', 'В страницах по 8 КБ измеряются другие параметры, например shared_buffers: у него unit = 8kB.', NULL),
        ('option', 'Что верно для значений user, superuser и internal столбца context в pg_settings?', 'user — любой пользователь может изменить параметр в своём сеансе, например work_mem', 'user — любой пользователь меняет параметр в сеансе', 'Для этого достаточно команды SET.', 'Для этого достаточно команды SET: любой пользователь может изменить параметр в своём сеансе, например work_mem.'),
        ('option', 'Что верно для значений user, superuser и internal столбца context в pg_settings?', 'superuser — в своём сеансе параметр может изменить суперпользователь или роль, которой выдано право SET на этот параметр', 'superuser — меняет в сеансе суперпользователь или роль с правом SET', 'Пример — log_statement: обычная роль получит ошибку «нет прав для изменения параметра».', 'В своём сеансе параметр может изменить суперпользователь или роль, которой выдано право SET на этот параметр. Пример — log_statement: обычная роль получит ошибку «нет прав для изменения параметра».'),
        ('option', 'Что верно для значений user, superuser и internal столбца context в pg_settings?', 'internal — параметр изменить нельзя, например block_size', 'internal — параметр нельзя изменить (block_size)', 'Параметр internal нельзя изменить ни файлом конфигурации, ни командой SET; например, block_size задаётся при сборке сервера.', NULL),
        ('option', 'Что верно для значений user, superuser и internal столбца context в pg_settings?', 'internal — параметр меняется только командой ALTER SYSTEM', 'internal — параметр меняется командой ALTER SYSTEM', 'Параметры internal нельзя изменить никак: ALTER SYSTEM ответит, что параметр нельзя изменить.', NULL),
        ('option', 'Что делает команда ALTER SYSTEM RESET ALL?', 'Сразу возвращает всем параметрам значения по умолчанию на работающем сервере', 'Сразу возвращает все параметры к значениям по умолчанию', 'Действующие значения изменятся только после перечитывания конфигурации.', NULL),
        ('option', 'Что делает команда ALTER SYSTEM RESET ALL?', 'Сбрасывает все параметры текущего сеанса к значениям из reset_val', 'Сбрасывает параметры сеанса к значениям из reset_val', 'Это делает команда RESET ALL без ALTER SYSTEM.', NULL),
        ('option', 'Что делает команда ALTER SYSTEM RESET ALL?', 'Удаляет все параметры из postgresql.conf', 'Удаляет все параметры из файла postgresql.conf', 'ALTER SYSTEM работает только с файлом postgresql.auto.conf.', NULL),
        ('option', 'Что делает команда ALTER SYSTEM RESET ALL?', 'Удаляет из postgresql.auto.conf все параметры, заданные через ALTER SYSTEM; изменения вступят в силу после перечитывания конфигурации или перезапуска', 'Удаляет из postgresql.auto.conf все заданные параметры', 'ALTER SYSTEM меняет только файл, а действующие значения остаются прежними до перечитывания. Параметрам с context = postmaster одного перечитывания мало, нужен перезапуск.', 'Удаляет из postgresql.auto.conf все параметры, заданные через ALTER SYSTEM; изменения вступят в силу после перечитывания конфигурации или перезапуска. ALTER SYSTEM меняет только файл, а действующие значения остаются прежними до перечитывания. Параметрам с context = postmaster одного перечитывания мало, нужен перезапуск.'),
        ('option', 'Приложение работает через пул соединений в режиме пула транзакций и внутри своей транзакции меняет параметр. Как это сделать, чтобы изменение не повлияло на транзакции других клиентов?', 'Командой ALTER ROLE ... SET', 'Командой ALTER ROLE ... SET для роли', 'Это значение по умолчанию для новых сеансов роли, а не для одной транзакции.', NULL),
        ('option', 'Приложение работает через пул соединений в режиме пула транзакций и внутри своей транзакции меняет параметр. Как это сделать, чтобы изменение не повлияло на транзакции других клиентов?', 'Командой ALTER SYSTEM SET и вызовом pg_reload_conf()', 'Командой ALTER SYSTEM SET и перечитыванием', 'Это изменит значение для всего сервера.', NULL),
        ('option', 'Приложение работает через пул соединений в режиме пула транзакций и внутри своей транзакции меняет параметр. Как это сделать, чтобы изменение не повлияло на транзакции других клиентов?', 'Командой SET LOCAL или функцией set_config с третьим аргументом true: значение действует только до конца текущей транзакции', 'Командой SET LOCAL или set_config(…, true)', 'После COMMIT или ROLLBACK параметр вернётся к прежнему значению.', 'Значение действует только до конца текущей транзакции: после COMMIT или ROLLBACK параметр вернётся к прежнему значению; set_config с третьим аргументом true работает так же.'),
        ('option', 'Приложение работает через пул соединений в режиме пула транзакций и внутри своей транзакции меняет параметр. Как это сделать, чтобы изменение не повлияло на транзакции других клиентов?', 'Командой SET: значение действует до конца сеанса', 'Командой SET, значение действует до конца сеанса', 'Через пул один сеанс сервера обслуживает и чужие транзакции, и они увидят изменённое значение.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
